mapper.select:
SELECT p.id, p.email, p.phone, p.created_at
FROM person p
WHERE p.workspace_id = #{workspaceId}
  AND p.id > #{afterId}
  AND p.suspended_at IS NULL
  AND p.provision_ceased_at IS NULL
  AND (
    (p.email IS NOT NULL AND TRIM(p.email) <> '')
    OR (p.phone IS NOT NULL AND TRIM(p.phone) <> '')
  )
ORDER BY p.id
LIMIT #{limit}

SELECT c.id, c.website, c.created_at
FROM company c
WHERE c.workspace_id = #{workspaceId}
  AND c.id > #{afterId}
  AND c.website IS NOT NULL
  AND TRIM(c.website) <> ''
ORDER BY c.id
LIMIT #{limit}

SELECT ci.company_id AS record_id, ci.kind, ci.normalized_value
FROM company_identity ci
JOIN company c ON c.workspace_id = ci.workspace_id AND c.id = ci.company_id
WHERE ci.workspace_id = #{workspaceId}
  AND ci.company_id IN

    #{recordId}

mapper.insert:
INSERT INTO person_identity (
  workspace_id, person_id, kind, `value`, normalized_value,
  source_system, source_channel, source_external_id, source_row_ref,
  acquired_at, purpose_of_use_code
)
SELECT p.workspace_id, p.id, 'email', p.email, #{normalizedValue},
       'backfill', 'person.email', NULL, CONCAT('person:', p.id),
       p.created_at, NULL
FROM person p
WHERE p.workspace_id = #{workspaceId}
  AND p.id = #{personId}
  AND CAST(p.email AS BINARY) = CAST(#{rawValue} AS BINARY)
  AND p.suspended_at IS NULL
  AND p.provision_ceased_at IS NULL
  AND NOT EXISTS (
    SELECT 1
    FROM person_identity existing
    WHERE existing.workspace_id = #{workspaceId}
      AND existing.person_id = #{personId}
      AND existing.kind = 'email'
      AND existing.normalized_value = #{normalizedValue}
  )
ON DUPLICATE KEY UPDATE id = id

